// BEFORE: one stable two-case switch, used in exactly one function
 function discount(o: Order): number {
   return o.coupon === 'NONE' ? 0 : o.subtotal * 0.1;
 }

// AFTER: a polymorphic hierarchy
+abstract class CouponPolicy { abstract amount(o: Order): number; }
+class NoCoupon extends CouponPolicy { amount() { return 0; } }
+class TenPercent extends CouponPolicy { amount(o: Order) { return o.subtotal * 0.1; } }
+
+function policyFor(o: Order): CouponPolicy {
+  return o.coupon === 'NONE' ? new NoCoupon() : new TenPercent();
+}
+function discount(o: Order): number { return policyFor(o).amount(o); }
